ROOT=Path('/workspace/sites/qogam-idea-atlas');R=Path('/workspace/scratch/eca73549458c')
def sections(file,prefix):
    raw=file.read_text();out={}
    for m in re.finditer(r'^## (.+)\n([\s\S]*?)(?=^## |\Z)',raw,re.M):
        name,body=m.groups();blocks=[];table=[]
        for line in body.splitlines()+['']:
            if line.startswith('|'):
                row=[s.strip() for s in line.strip('|').split('|')]
                if not all(re.fullmatch(r'[-: ]+',s) for s in row):table.append(row)
                continue
            if table:blocks.append({'type':'table','rows':table});table=[]
            if not line.strip():continue
            if line.startswith(('Сайттағы','Интерактив.','Сайтта «','Сайтта пайдаланушы','Сайттың қос','Қазақстан бойынша','[','Төмендегі сілтемелер')):continue
            line=re.sub(r'\[(\d+(?:,\s*\d+)*)\]',lambda m:' '.join('['+prefix+n.strip()+']' for n in m[1].split(',')),line)
            blocks.append({'type':'p','text':line})
        # Convert table citations too.
        for b in blocks:
            if b['type']=='table':b['rows']=[[re.sub(r'\[(\d+(?:,\s*\d+)*)\]',lambda m:' '.join('['+prefix+n.strip()+']' for n in m[1].split(',')),s) for s in row] for row in b['rows']]
        out[name]=blocks
    return out
